<template><div><DsPageHeader title="Grupos e classificações" subtitle="Classificações usadas nas faixas de normalidade" icon="tags"/><DsPageShell><div class="flex justify-end gap-2 mb-4"><DsButton v-if="auth.isAdmin" variant="secondary" @click="openGroup()">Novo grupo</DsButton><DsButton v-if="auth.isAdmin&&groups.length" variant="success" @click="openClass()">Nova classificação</DsButton></div><DsAlert v-if="error" variant="error">{{error}}</DsAlert><div v-else class="space-y-4"><section v-for="g in groups" :key="g.codGrupo" class="border rounded-2xl p-4"><div class="flex justify-between items-center mb-3"><div><h3 class="font-semibold">{{g.nome}}</h3><small class="text-gray-500">{{g.quantidadeClassificacoes}} classificação(ões)</small></div><div v-if="auth.isAdmin" class="flex gap-2"><DsButton size="sm" variant="secondary" @click="openGroup(g)">Editar</DsButton><DsButton size="sm" variant="danger" @click="removeGroup(g)">Excluir</DsButton></div></div><div class="flex flex-wrap gap-2"><span v-for="c in classes.filter(x=>x.codGrupo===g.codGrupo)" :key="c.codClassificacao" class="inline-flex items-center gap-2 border rounded-full px-3 py-1 text-sm">{{c.nome}}<button v-if="auth.isAdmin" class="text-blue-600" @click="openClass(c)">editar</button><button v-if="auth.isAdmin" class="text-red-600" @click="removeClass(c)">×</button></span><span v-if="!classes.some(x=>x.codGrupo===g.codGrupo)" class="text-sm text-gray-500">Nenhuma classificação.</span></div></section></div></DsPageShell><DsModal v-model="groupModal" :title="groupEditing?'Editar grupo':'Novo grupo'"><DsInput v-model="groupName" label="Nome"/><template #footer><DsButton variant="secondary" @click="groupModal=false">Cancelar</DsButton><DsButton @click="saveGroup">Salvar</DsButton></template></DsModal><DsModal v-model="classModal" :title="classEditing?'Editar classificação':'Nova classificação'"><div class="space-y-3"><DsInput v-model="classForm.nome" label="Nome"/><DsSelect v-model="classForm.codGrupo" label="Grupo"><option v-for="g in groups" :key="g.codGrupo" :value="String(g.codGrupo)">{{g.nome}}</option></DsSelect></div><template #footer><DsButton variant="secondary" @click="classModal=false">Cancelar</DsButton><DsButton @click="saveClass">Salvar</DsButton></template></DsModal></div></template>
<script setup lang="ts">definePageMeta({layout:'default'});const api=useApi(),auth=useAuthStore(),swal=useSwal();const groups=ref<any[]>([]),classes=ref<any[]>([]),error=ref(''),groupModal=ref(false),classModal=ref(false),groupEditing=ref<any>(null),classEditing=ref<any>(null),groupName=ref(''),classForm=reactive({nome:'',codGrupo:''});async function load(){try{const[g,c]=await Promise.all([api.get<any>('/api/web/cadastros/classificacoes/grupos'),api.get<any>('/api/web/cadastros/classificacoes')]);groups.value=g.data||[];classes.value=c.data||[]}catch(e){error.value=e instanceof Error?e.message:'Erro ao carregar.'}}function openGroup(g?:any){groupEditing.value=g||null;groupName.value=g?.nome||'';groupModal.value=true}function openClass(c?:any){classEditing.value=c||null;classForm.nome=c?.nome||'';classForm.codGrupo=String(c?.codGrupo||groups.value[0]?.codGrupo||'');classModal.value=true}async function saveGroup(){try{const body={nome:groupName.value};groupEditing.value?await api.put(`/api/web/cadastros/classificacoes/grupos/${groupEditing.value.codGrupo}`,body):await api.post('/api/web/cadastros/classificacoes/grupos',body);groupModal.value=false;await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao salvar.','error')}}async function saveClass(){try{const body={nome:classForm.nome,codGrupo:Number(classForm.codGrupo)};classEditing.value?await api.put(`/api/web/cadastros/classificacoes/${classEditing.value.codClassificacao}`,body):await api.post('/api/web/cadastros/classificacoes',body);classModal.value=false;await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao salvar.','error')}}async function removeGroup(g:any){const c=await swal.confirm('Excluir grupo',`Excluir "${g.nome}"?`);if(!c?.isConfirmed)return;try{await api.del(`/api/web/cadastros/classificacoes/grupos/${g.codGrupo}`);await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao excluir.','error')}}async function removeClass(x:any){const c=await swal.confirm('Excluir classificação',`Excluir "${x.nome}"?`);if(!c?.isConfirmed)return;try{await api.del(`/api/web/cadastros/classificacoes/${x.codClassificacao}`);await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao excluir.','error')}}onMounted(load)</script>
